mapper.select:
SELECT show_english, show_chinese, review_direction, daily_new_limit, daily_review_limit
FROM sr_english_vocabulary_study_setting
WHERE account_id = #{accountId}

SELECT COUNT(DISTINCT word_id) FROM sr_english_vocabulary_mode_memory mm
WHERE account_id = #{accountId} AND next_review_at <= #{now}
AND EXISTS (SELECT 1 FROM sr_english_vocabulary_word w WHERE w.id = mm.word_id)

SELECT word_id FROM sr_english_vocabulary_memory
WHERE account_id = #{accountId} AND learning_status = 'ACTIVE' AND next_review_at <= #{now}
ORDER BY next_review_at, word_id
LIMIT #{limit}

SELECT w.id FROM sr_english_vocabulary_word w
WHERE w.theme_id = #{themeId}
  AND NOT EXISTS (
      SELECT 1 FROM sr_english_vocabulary_memory m
      WHERE m.account_id = #{accountId} AND m.word_id = w.id
  )
ORDER BY w.sort_order, w.id
LIMIT #{limit}
